$$
\begin{array}{r l} I _ {n} & = \int_ {0} ^ {1} (\ln x) ^ {n} \mathrm{d} \left(\frac {x ^ {m + 1}}{m + 1}\right) = \frac {x ^ {m + 1}}{m + 1} (\ln x) ^ {n} \Big | _ {0} ^ {1} - \int_ {0} ^ {1} \frac {x ^ {m + 1}}{m + 1} \cdot n (\ln x) ^ {n - 1} \cdot \frac {1}{x} \mathrm{d} x \\ & = - \frac {n}{m + 1} \int_ {0} ^ {1} x ^ {m} (\ln x) ^ {n - 1} \mathrm{d} x \quad \left(\lim _ {x \to 0} \frac {x ^ {m + 1}}{m - 1} (\ln x) ^ {n} = 0\right). \end{array}
$$

$$
\begin{array}{r l} I _ {n} & = - \frac {n}{m + 1} \cdot I _ {n - 1} = (- 1) \frac {n}{m + 1} \cdot (- 1) \frac {n - 1}{m + 1} \cdot I _ {n - 2} \\ & = \dots = \frac {(- 1) n}{m + 1} \cdot \frac {(- 1) (n - 1)}{m + 1} \cdot \dots \cdot \frac {(- 1) 2}{m + 1} \cdot I _ {1}. \end{array}
$$

$$
\begin{array}{r l} I _ {1} & = \int_ {0} ^ {1} x ^ {m} \ln x \mathrm{d} x = \int_ {0} ^ {1} \ln x \mathrm{d} \left(\frac {x ^ {m + 1}}{m + 1}\right) \\ & = \frac {x ^ {m + 1}}{m + 1} \ln x \Big | _ {0} ^ {1} - \int_ {0} ^ {1} \frac {x ^ {m + 1}}{m + 1} \cdot \frac {1}{x} \mathrm{d} x = \frac {- 1}{(m + 1) ^ {2}}, \end{array}
$$
